        '.html': '🌐', '.css': '🎨', '.txt': '📄', '.log': '📃',
        '.bak': '💾', '.tmp': '🗑', '.vba': '📊', '.bas': '📊'
    }
    return icons.get(ext, '📄')

# === ВАЖНЫЕ ФАЙЛЫ (ПОЛЬЗОВАТЕЛЬСКИЕ ОТМЕТКИ) ===
