    action = payload.get('action', 'toggle')

    important = load_important_files()

    if action == 'add':
        important.add(path)
    elif action == 'remove':
        important.discard(path)
    else:
        if path in important:
            important.discard(path)
        else:
            important.add(path)

    save_important_files(important)
    return JSONResponse({"success": True, "important": list(important)})

